CREATE OR REPLACE FORCE EDITIONABLE VIEW "USRSIHO"."CODEAC_NMLOPROC_SDW" ("MARCA_ACT", "CMD", "OLD_PRO_KEYPRO", "OLD_PRO_DESPRO", "OLD_PRO_KEYCIA", "NEW_PRO_KEYCIA", "NEW_PRO_KEYPRO", "NEW_PRO_DESPRO", "ORDERID1", "ORDERID2") AS 
  SELECT MARCA_ACT,CMD,OLD_PRO_KEYPRO,OLD_PRO_DESPRO,OLD_PRO_KEYCIA,NEW_PRO_KEYCIA,NEW_PRO_KEYPRO,NEW_PRO_DESPRO,ORDERID1,ORDERID2 FROM nmloproc_sdw;
